const state={username:localStorage.getItem('laliga.user')||'',uid:localStorage.getItem('laliga.uid')||'',token:sessionStorage.getItem('laliga.token')||'',step:'username',selected:'',route:'matches',root:null,main:{matches:[],eso4players:[]},error:'',busy:false,offline:localStorage.getItem('laliga.offline')==='1',offlineAvailable:false,unlocked:false,adminScreen:'',adminID:null,role:'normal'};
let stream=null,roleStream=null,streamMode=null,streamValue=null,streamHasValue=false,pendingStreamRender=false,reconcileTimer=null,reconciling=false,reconcileRetryAt=0,localClockTimer=null;
