const user=()=>state.root?.users?.[state.username], linked=(key)=>{let u=state.root?.users?.[key];return u?.isWho!=null&&u.isWho!==-1&&players().some(p=>p.id===u.isWho)};
const money=x=>Number(x||0).toLocaleString('es-ES');
const fmtDate=x=>new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'2-digit',year:'2-digit'}).format(new Date((Number(x)+978307200)*1000));
const request=async(url,options={})=>{let r=await fetch(url,options);if(!r.ok)throw Error(r.status===412?'La base de datos ha cambiado durante la edición. Vuelve a cargar e inténtalo de nuevo.':`Firebase: ${r.status}`);return r};
async function loadMain(){if(state.offline){state.main=JSON.parse(localStorage.getItem('laliga.offlineData')||'{}').main||{matches:[],eso4players:[]};return}let r=await request(`${DB}/main.json`);state.main=(await r.json())||{matches:[],eso4players:[]};}
async function loadRoot(){if(state.offline){state.root=JSON.parse(localStorage.getItem('laliga.offlineData')||'{}');state.main=state.root.main||{matches:[],eso4players:[]};state.etag=localStorage.getItem('laliga.offlineData');return}let r=await request(`${DB}/.json`,{headers:{'X-Firebase-ETag':'true'}});let tag=r.headers.get('ETag');if(!tag)throw Error('Firebase no ha proporcionado una versión para guardar los cambios de forma segura.');state.root=await r.json()||{};state.etag=tag;state.main=state.root.main||{matches:[],eso4players:[]};}
async function mutate(fn){await loadRoot();let root=structuredClone(state.root);fn(root);if(state.offline){if(localStorage.getItem('laliga.offlineData')!==state.etag)throw Error('La base de datos ha cambiado durante la edición. Vuelve a cargar e inténtalo de nuevo.');localStorage.setItem('laliga.offlineData',JSON.stringify(root));await loadRoot();return}await request(`${DB}/.json`,{method:'PUT',headers:{'Content-Type':'application/json','if-match':state.etag},body:JSON.stringify(root)});state.root=root;state.main=root.main||{matches:[],eso4players:[]}}
async function run(fn){state.busy=true;state.error='';render();try{await fn()}catch(err){state.error=err.message||String(err)}finally{state.busy=false;render()}}
function login(){return `<div class="login"><form class="login-inner" id="login"><h1>⚽ LaLiga Brains</h1>${state.step==='username'?`<b>Introduce tu nombre de usuario</b><input name="username" placeholder="Nombre de usuario" autocomplete="username" required><button class="primary">Continuar</button>`:state.step==='signIn'?`<b>¡Bienvenido de nuevo, ${e(state.selected)}!</b><input name="password" type="password" placeholder="Contraseña" autocomplete="current-password" required><button class="primary">Iniciar sesión</button><button type="button" data-action="change-user">Cambiar usuario</button>`:`<b>Crear una cuenta</b><span class="muted">Usuario: ${e(state.selected)}</span><input name="password" type="password" placeholder="Contraseña" autocomplete="new-password" required><input name="repeat" type="password" placeholder="Repite la contraseña" autocomplete="new-password" required><button class="primary">Crear cuenta</button><button type="button" data-action="change-user">Cambiar usuario</button>`}${state.busy?'<span>Cargando…</span>':''}${state.error?`<p class="error">${e(state.error)}</p>`:''}</form></div>`}
function header(){return `<header class="header"><h1>⚽ LaLiga Brains</h1><div class="nav-strip">${[['matches','matchesIcon','Partidos'],['goals','goalsIcon','Goles'],['rankings','rankingsIcon','Clasificaciones'],['id','idIcon','ID'],['predictions','predictionsIcon','Predicciones'],['quiz','quizIcon','Quiz'],...(isAdministrator()?[['kingdom','kingdomIcon','Administración']]:[])].map(([route,img,label])=>`<button class="nav-button" data-route="${route}" aria-label="${label}"><img src="assets/${img}.${img==='quizIcon'?'svg':'png'}" alt=""></button>`).join('')}${state.username!=='adri'?`<span>${e(state.username)}</span>`:''}</div></header>`}
function scorerNames(m){let ids=arr(m?.scorers);return [...new Set(ids)].map(id=>{let p=players().find(p=>p.id===id),name=id===-1?'Desconocido':p?.name;if(!name)return null;let count=ids.filter(i=>i===id).length;return {id,name:name+(count>1?` x${count}`:'')}}).filter(Boolean)}
function chart(which){
  const ms=arr(state.main.matches);let a=0,b=0;
  const series=ms.map(m=>{if(which==='points'){a+=m.eso3Score>m.eso4Score?3:m.eso3Score===m.eso4Score?1:0;b+=m.eso4Score>m.eso3Score?3:m.eso3Score===m.eso4Score?1:0}else{a+=m.eso3Score;b+=m.eso4Score}return {id:m.id,a,b}});
  if(!series.length)return `<div class="chart-empty" aria-label="${which==='points'?'Puntos':'Goles'}"></div>`;
  const maximum=Math.max(1,...series.flatMap(x=>[x.a,x.b])),rough=maximum/4,power=10**Math.floor(Math.log10(rough)),step=[1,2,5,10].map(n=>n*power).find(n=>n>=rough)||1,top=Math.ceil(maximum/step)*step;
  const ticks=Array.from({length:Math.round(top/step)+1},(_,i)=>i*step);
  const coords=key=>series.map((point,i)=>`${(series.length===1?500:i/(series.length-1)*1000).toFixed(2)},${(180-point[key]/top*180).toFixed(2)}`).join(' ');
  let count=series.length, stride=Math.max(1,Math.ceil(count/7)), xlabels=series.map((p,i)=>i%stride===0||(i===count-1&&i%stride>=stride/2)?`<span class="chart-x-label" style="left:${count===1?50:i/(count-1)*100}%">${e(p.id)}</span>`:'').join('');
  return `<figure class="swift-chart" role="img" aria-label="${which==='points'?'Puntos':'Goles'}: evolución acumulada de 3º ESO y 4º ESO"><div class="chart-plot"><div class="chart-grid">${ticks.map(t=>`<div class="chart-grid-line" style="bottom:${t/top*100}%"><span>${e(t)}</span></div>`).join('')}<svg viewBox="0 0 1000 180" preserveAspectRatio="none" aria-hidden="true"><polyline points="${coords('a')}"/><polyline class="second" points="${coords('b')}"/></svg></div><div class="chart-x-axis">${xlabels}</div></div><div class="chart-legend"><span><i class="legend-blue"></i>3º ESO</span><span><i class="legend-green"></i>4º ESO</span></div></figure>`;
}
function streak(team){let ms=matches();if(!ms.length||ms[0].eso3Score===ms[0].eso4Score)return '0';let win=(m)=>team===3?m.eso3Score>m.eso4Score:m.eso4Score>m.eso3Score;let first=win(ms[0]),n=1;for(const m of ms.slice(1)){if(m.eso3Score===m.eso4Score||win(m)!==first)break;n++}return `${n} ${first?'W':'L'}`}
function matchHome(){let ms=matches(),p3=0,p4=0,g3=0,g4=0;for(let m of ms){g3+=m.eso3Score;g4+=m.eso4Score;p3+=m.eso3Score>m.eso4Score?3:m.eso3Score===m.eso4Score?1:0;p4+=m.eso4Score>m.eso3Score?3:m.eso3Score===m.eso4Score?1:0}let last=ms[0],names=scorerNames(last);return `<div class="split"><div class="stats"><b>3º ESO</b><span></span><b>4º ESO</b><span><span class="pill">${p3}</span></span><span class="muted">puntos</span><span><span class="pill">${p4}</span></span><span>${g3}</span><span class="muted">goles</span><span>${g4}</span><span>${streak(3)}</span><span class="muted">racha</span><span>${streak(4)}</span></div><div class="latest"><h2>Último Partido</h2><div class="scores"><span class="score">${last?.eso3Score??'-'}</span><span>vs.</span><span class="score">${last?.eso4Score??'-'}</span></div><h3>Goleadores de 4º ESO</h3><div class="latest-scorers">${names.length?names.map(p=>`<button class="scorer-pill ${p.id===-1?'unknown':''}" data-route="goals/${p.id}" ${p.id===-1?'disabled':''}>${e(p.name)}</button>`).join(''):'<span>No hay goleadores en este partido</span>'}</div></div></div><button class="link-block" data-route="matches/list">Ver todos los partidos</button><div class="chart-label">Puntos</div>${chart('points')}<div class="chart-label">Goles</div>${chart('goals')}`}
function matchList(){return `<button class="back" data-route="matches">Atrás</button><ul class="list">${matches().map(m=>`<li class="${state.route===`matches/${m.id}`?'highlight':''}"><span>${fmtDate(m.date)}</span><span class="pill">${m.eso3Score}/${m.eso4Score}</span><span>⚽: </span>${scorerNames(m).map(p=>`<button class="green" data-route="goals/${p.id}" ${p.id===-1?'disabled':''}>${e(p.name)}</button>`).join('')||'❌'}</li>`).join('')}</ul>`}
function goals(){if(state.route==='goals')return `<h2 class="goals-title">Goles</h2><ul class="list goals">${players().filter(p=>p.id!==-1).sort((a,b)=>b.goals-a.goals).map(p=>`<li><button data-route="goals/${p.id}"><span>${e(p.name)}</span><span>${p.goals} ⚽</span></button></li>`).join('')}</ul>`;let id=Number(state.route.split('/')[1]),p=players().find(x=>x.id===id);if(!p)return '<button data-route="goals">Atrás</button> Jugador no encontrado';let linkedUser=Object.keys(state.root?.users||{}).sort().find(k=>state.root.users[k]?.isWho===id);return `<div class="stack"><div class="row"><button data-route="goals">Atrás</button><h3>Info de ${e(p.name)}</h3></div><div class="row"><span class="score">${p.goals}</span> Goles</div>${linkedUser?`<button data-route="id/${e(linkedUser)}">Ver perfil de usuario</button>`:''}<b>Goles en:</b><ul class="list goal-matches">${matches().filter(m=>arr(m.scorers).includes(id)).map(m=>`<li><button data-route="matches/${m.id}"><span>Partido #${m.id} · ${fmtDate(m.date)}</span><span>${arr(m.scorers).filter(x=>x===id).length} ⚽</span></button></li>`).join('')}</ul></div>`}
const owned=u=>u?.ownedDecorations||{},worth=u=>(u?.coins||0)+Object.values(owned(u)).reduce((a,b)=>a+Math.max(0,Number(b)||0),0);
const symbols=['🙂','😎','🐱','🐶','🌟','🐼','🦊','🐯','🐸','🐧','🦁','🐨','🦄','🐙','🐲','🤖','👑','🍀','🌈','🔥','🚀','💎','🏆','🎮','⚽'];
