  if(wanted==='main'&&state.username!=='adri'){const userName=state.username;const roleFeed=new EventSource(`${DB}/users/${encodeURIComponent(userName)}/role.json`);roleStream=roleFeed;roleFeed.addEventListener('put',event=>{if(roleStream!==roleFeed||userName!==state.username)return;try{const payload=JSON.parse(event.data);if(payload.path!=='/')return;state.role=payload.data==='administrator'?'administrator':'normal';requestStreamRender()}catch(err){console.error('Firebase role stream:',err)}});roleFeed.addEventListener('cancel',()=>{if(roleStream!==roleFeed)return;roleFeed.close();roleStream=null;state.role='normal';requestStreamRender()});roleFeed.addEventListener('auth_revoked',()=>{if(roleStream!==roleFeed)return;roleFeed.close();roleStream=null;state.role='normal';requestStreamRender()})}
