  const current=new EventSource(wanted==='root'?`${DB}/.json`:`${DB}/main.json`);stream=current;
  const receive=type=>event=>{if(stream!==current)return;try{const payload=JSON.parse(event.data);if(!streamHasValue&&(type!=='put'||payload.path!=='/'))return;streamValue=applyStreamEvent(streamValue,type,payload);streamHasValue=true;if(wanted==='root'){state.root=streamValue||{};state.main=state.root.main||{matches:[],eso4players:[]};state.role=state.root.users?.[state.username]?.role==='administrator'?'administrator':'normal'}else state.main=streamValue||{matches:[],eso4players:[]};if(['Se ha perdido la conexión con Firebase. Reconectando…','No se ha podido conectar con Firebase.','Firebase ha rechazado la lectura de datos.'].includes(state.error))state.error='';requestStreamRender();scheduleReconciliation()}catch(err){console.error('Firebase stream:',err)}};
