window.addEventListener('pagehide',()=>{if(stream){stream.close();stream=null;streamMode=null}if(roleStream){roleStream.close();roleStream=null}if(reconcileTimer){clearTimeout(reconcileTimer);reconcileTimer=null}});
window.addEventListener('pageshow',()=>{syncStream()});
function scheduleReconciliation(){
  if(reconcileTimer){clearTimeout(reconcileTimer);reconcileTimer=null}
  if(!state.username||!state.unlocked||state.route!=='kingdom'||!state.root||reconciling)return;
  const copy=structuredClone(state.root),changed=reconcile(copy);
  if(changed){if(editingInProgress())return;reconcileTimer=setTimeout(async()=>{reconcileTimer=null;if(reconciling||editingInProgress())return;reconciling=true;try{await mutate(reconcile);reconcileRetryAt=0;requestStreamRender()}catch(err){reconcileRetryAt=Date.now()+60000;state.error='Error al comprobar los apoyos: '+err.message;requestStreamRender()}finally{reconciling=false;scheduleReconciliation()}},Math.max(0,reconcileRetryAt-Date.now()));return}
  const deadlines=Object.values(state.root.predictions||{}).map(b=>Number(b?.expiresAt)).filter(Number.isFinite);if(!deadlines.length)return;
  const delay=Math.max(0,Math.min(2147483647,Math.ceil((Math.min(...deadlines)*1000-Date.now())+20)));reconcileTimer=setTimeout(()=>{reconcileTimer=null;scheduleReconciliation()},delay);
}

// The clock refresh changes only the displayed betting window; it makes no database request.
